import '@servicenow/sdk/global'
import { action, Subflow, wfa, FlowArray } from '@servicenow/sdk/automation'
import { BooleanColumn, DateTimeColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'

/**
 * Test Subflow for FlowArray with primitive types in assignSubflowOutputs
 * This tests String[], Integer[], Boolean[], and DateTime[] arrays
 */
export const testSubflowPrimitiveArrays = Subflow(
    {
        $id: Now.ID['test_subflow_primitive_arrays'],
        name: 'Test Subflow - Primitive Arrays',
        description: 'Subflow with primitive type FlowArray outputs',
        inputs: {
            inputString: StringColumn({ label: 'Input String', mandatory: false }),
            inputNumber: IntegerColumn({ label: 'Input Number', mandatory: false }),
            inputBoolean: BooleanColumn({ label: 'Input Boolean', mandatory: false }),
            inputDate: DateTimeColumn({ label: 'Input Date', mandatory: false }),
        },
        outputs: {
            // FlowArray of strings
            stringList: FlowArray({
                label: 'String List',
                mandatory: false,
                elementType: StringColumn({ label: 'String Item', mandatory: false }),
                childName: 'stringItem',
            }),

            // FlowArray of integers
            numberList: FlowArray({
                label: 'Number List',
                mandatory: false,
                elementType: IntegerColumn({ label: 'Number Item', mandatory: false }),
                childName: 'numberItem',
            }),

            // FlowArray of booleans
            booleanList: FlowArray({
                label: 'Boolean List',
                mandatory: false,
                elementType: BooleanColumn({ label: 'Boolean Item', mandatory: false }),
                childName: 'booleanItem',
            }),

            // FlowArray of datetime
            dateList: FlowArray({
                label: 'Date List',
                mandatory: false,
                elementType: DateTimeColumn({ label: 'Date Item', mandatory: false }),
                childName: 'dateItem',
            }),
        },
    },
    (params) => {
        // TEST 1: String array with values
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test1_string_array'], annotation: 'TEST 1: String Array' },
            params.outputs,
            {
                stringList: ['apple', 'banana', 'cherry'],
            }
        )

        // TEST 2: Integer array with values
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test2_integer_array'], annotation: 'TEST 2: Integer Array' },
            params.outputs,
            {
                numberList: [10, 20, 30, 40],
            }
        )

        // TEST 3: Boolean array with values
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test3_boolean_array'], annotation: 'TEST 3: Boolean Array' },
            params.outputs,
            {
                booleanList: [true, false, true],
            }
        )

        // TEST 4: DateTime array with values
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test4_datetime_array'], annotation: 'TEST 4: DateTime Array' },
            params.outputs,
            {
                dateList: ['2024-01-01 10:00:00', '2024-02-15 14:30:00'],
            }
        )

        // TEST 5: Empty string array
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test5_empty_string_array'], annotation: 'TEST 5: Empty String Array' },
            params.outputs,
            {
                stringList: [],
            }
        )

        // TEST 6: Empty integer array
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test6_empty_integer_array'], annotation: 'TEST 6: Empty Integer Array' },
            params.outputs,
            {
                numberList: [],
            }
        )

        // TEST 7: Empty boolean array
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test7_empty_boolean_array'], annotation: 'TEST 7: Empty Boolean Array' },
            params.outputs,
            {
                booleanList: [],
            }
        )

        // TEST 8: String array with datapills
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test8_string_array_datapills'], annotation: 'TEST 8: String Array with Datapills' },
            params.outputs,
            {
                stringList: [
                    'Static value',
                    wfa.dataPill(params.inputs.inputString, 'string'),
                    `Computed: ${wfa.dataPill(params.inputs.inputString, 'string')}`,
                ],
            }
        )

        // TEST 9: Integer array with datapills
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test9_integer_array_datapills'], annotation: 'TEST 9: Integer Array with Datapills' },
            params.outputs,
            {
                numberList: [100, wfa.dataPill(params.inputs.inputNumber, 'integer'), 200],
            }
        )

        // TEST 10: Boolean array with datapills
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test10_boolean_array_datapills'], annotation: 'TEST 10: Boolean Array with Datapills' },
            params.outputs,
            {
                booleanList: [true, wfa.dataPill(params.inputs.inputBoolean, 'boolean'), false],
            }
        )

        // TEST 11: DateTime array with datapills
        wfa.flowLogic.assignSubflowOutputs(
            { $id: Now.ID['test11_datetime_array_datapills'], annotation: 'TEST 11: DateTime Array with Datapills' },
            params.outputs,
            {
                dateList: [
                    '2024-01-01 10:00:00',
                    wfa.dataPill(params.inputs.inputDate, 'datetime'),
                    '2024-12-31 23:59:59',
                ],
            }
        )

        // Log completion
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_primitive_arrays_complete'] },
            { log_level: 'info', log_message: 'All primitive array tests completed' }
        )
    }
)
